def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    cnt = Counter(v for row in grid for v in row)
    block = max((c for c in cnt if c != 0), key=lambda c: cnt[c])
    cells = [(i,j) for i in range(h) for j in range(w) if grid[i][j]==block]
    r0,r1 = min(i for i,_ in cells), max(i for i,_ in cells)
    c0,c1 = min(j for _,j in cells), max(j for _,j in cells)
    dots = [(i,j) for i in range(h) for j in range(w) if grid[i][j] not in (0,block)]
    up    = {j for i,j in dots if i < r0}
    down  = {j for i,j in dots if i > r1}
    left  = {i for i,j in dots if j < c0}
    right = {i for i,j in dots if j > c1}
    out = [[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j] != 0:
                out[i][j] = grid[i][j]
    for i in range(r0, r1+1):
        if i not in left:  out[i][:c0] = [block]*c0
        if i not in right: out[i][c1+1:] = [block]*(w-c1-1)
    for j in range(c0, c1+1):
        if j not in up:   [out.__setitem__(i, out[i][:j]+[block]+out[i][j+1:]) for i in range(r0)]
        if j not in down: [out.__setitem__(i, out[i][:j]+[block]+out[i][j+1:]) for i in range(r1+1, h)]
    return out

